    30→// CapturePrePromptState captures current untracked files and transcript position before a prompt
    31→// and saves them to a state file.
    32→// Works correctly from any subdirectory within the repository.
    33→// The transcriptPath parameter is optional - if empty, transcript position won't be captured.
    34→func CapturePrePromptState(sessionID, transcriptPath string) error {
    35→	if sessionID == "" {
    36→		sessionID = unknownSessionID
    37→	}
    38→
    39→	// Get absolute path for tmp directory
    40→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
    41→	if err != nil {
    42→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
    43→	}
    44→
    45→	// Create tmp directory if it doesn't exist
    46→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
    47→		return fmt.Errorf("failed to create tmp directory: %w", err)
    48→	}
    49→
    50→	// Get list of untracked files (excluding .entire directory itself)
    51→	untrackedFiles, err := getUntrackedFilesForState()
    52→	if err != nil {
    53→		return fmt.Errorf("failed to get untracked files: %w", err)
    54→	}
    55→
    56→	// Get transcript position (last UUID and line count)
    57→	var transcriptPos TranscriptPosition
    58→	if transcriptPath != "" {
    59→		transcriptPos, err = GetTranscriptPosition(transcriptPath)
    60→		if err != nil {
    61→			// Log warning but don't fail - transcript position is optional
    62→			fmt.Fprintf(os.Stderr, "Warning: failed to get transcript position: %v\n", err)
    63→		}
    64→	}
    65→
    66→	// Create state file
    67→	stateFile := prePromptStateFile(sessionID)
    68→	state := PrePromptState{
    69→		SessionID:               sessionID,
    70→		Timestamp:               time.Now().UTC().Format(time.RFC3339),
    71→		UntrackedFiles:          untrackedFiles,
    72→		LastTranscriptUUID:      transcriptPos.LastUUID,
    73→		LastTranscriptLineCount: transcriptPos.LineCount,
    74→	}
    75→
    76→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
    77→	if err != nil {
    78→		return fmt.Errorf("failed to marshal state: %w", err)
    79→	}
    80→
    81→	if err := os.WriteFile(stateFile, data, 0o600); err != nil {
    82→		return fmt.Errorf("failed to write state file: %w", err)
    83→	}
    84→
    85→	fmt.Fprintf(os.Stderr, "Captured state before prompt: %d untracked files, transcript at line %d (uuid: %s)\n",
    86→		len(untrackedFiles), transcriptPos.LineCount, transcriptPos.LastUUID)
    87→	return nil
    88→}
