   136→// ComputeDeletedFiles returns files that were deleted during the session
   137→// (tracked files that no longer exist).
   138→func ComputeDeletedFiles() ([]string, error) {
   139→	repo, err := openRepository()
   140→	if err != nil {
   141→		return nil, err
   142→	}
   143→
   144→	worktree, err := repo.Worktree()
   145→	if err != nil {
   146→		return nil, err
   147→	}
   148→
   149→	status, err := worktree.Status()
   150→	if err != nil {
   151→		return nil, err
   152→	}
   153→
   154→	var deletedFiles []string
   155→	for file, st := range status {
   156→		// Skip .entire directory
   157→		if paths.IsInfrastructurePath(file) {
   158→			continue
   159→		}
   160→
   161→		// Find deleted files that haven't been staged yet
   162→		if st.Worktree == git.Deleted && st.Staging != git.Deleted {
   163→			deletedFiles = append(deletedFiles, file)
   164→		}
   165→	}
   166→
   167→	return deletedFiles, nil
   168→}
