   170→// FilterAndNormalizePaths converts absolute paths to relative and filters out
   171→// infrastructure paths and paths outside the repo.
   172→func FilterAndNormalizePaths(files []string, cwd string) []string {
   173→	var result []string
   174→	for _, file := range files {
   175→		relPath := paths.ToRelativePath(file, cwd)
   176→		if relPath == "" {
   177→			continue // outside repo
   178→		}
   179→		if paths.IsInfrastructurePath(relPath) {
   180→			continue // skip .entire directory
   181→		}
   182→		result = append(result, relPath)
   183→	}
   184→	return result
   185→}
