   235→// CapturePreTaskState captures current untracked files before a Task execution
   236→// and saves them to a state file.
   237→// Works correctly from any subdirectory within the repository.
   238→func CapturePreTaskState(toolUseID string) error {
   239→	if toolUseID == "" {
   240→		return errors.New("tool_use_id is required")
   241→	}
   242→
   243→	// Get absolute path for tmp directory
   244→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
   245→	if err != nil {
   246→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
   247→	}
   248→
   249→	// Create tmp directory if it doesn't exist
   250→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
   251→		return fmt.Errorf("failed to create tmp directory: %w", err)
   252→	}
   253→
   254→	// Get list of untracked files (excluding .entire directory itself)
   255→	untrackedFiles, err := getUntrackedFilesForState()
   256→	if err != nil {
   257→		return fmt.Errorf("failed to get untracked files: %w", err)
   258→	}
   259→
   260→	// Create state file
   261→	stateFile := preTaskStateFile(toolUseID)
   262→	state := PreTaskState{
   263→		ToolUseID:      toolUseID,
   264→		Timestamp:      time.Now().UTC().Format(time.RFC3339),
   265→		UntrackedFiles: untrackedFiles,
   266→	}
   267→
   268→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
   269→	if err != nil {
   270→		return fmt.Errorf("failed to marshal state: %w", err)
   271→	}
   272→
   273→	if err := os.WriteFile(stateFile, data, 0o600); err != nil {
   274→		return fmt.Errorf("failed to write state file: %w", err)
   275→	}
   276→
   277→	fmt.Fprintf(os.Stderr, "Captured state before task: %d untracked files\n", len(untrackedFiles))
   278→	return nil
   279→}
