   346→// preTaskFilePrefix is the prefix for pre-task state files
   347→const preTaskFilePrefix = "pre-task-"
   348→
   349→// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
   350→// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
   351→// When multiple pre-task files exist (nested subagents), returns the most recently
   352→// modified one.
   353→// Works correctly from any subdirectory within the repository.
   354→func FindActivePreTaskFile() (taskToolUseID string, found bool) {
   355→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
   356→	if err != nil {
   357→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
   358→	}
   359→	entries, err := os.ReadDir(tmpDirAbs)
   360→	if err != nil {
   361→		return "", false
   362→	}
   363→
   364→	var latestFile string
   365→	var latestTime time.Time
   366→
   367→	for _, entry := range entries {
   368→		if entry.IsDir() {
   369→			continue
   370→		}
   371→		name := entry.Name()
   372→		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
   373→			continue
   374→		}
   375→
   376→		// Check modification time for nested subagent handling
   377→		info, err := entry.Info()
   378→		if err != nil {
   379→			continue
   380→		}
   381→		if latestFile == "" || info.ModTime().After(latestTime) {
   382→			latestFile = name
   383→			latestTime = info.ModTime()
   384→		}
   385→	}
   386→
   387→	if latestFile == "" {
   388→		return "", false
   389→	}
   390→
   391→	// Extract tool_use_id from filename: pre-task-<tool_use_id>.json
   392→	toolUseID := strings.TrimPrefix(latestFile, preTaskFilePrefix)
   393→	toolUseID = strings.TrimSuffix(toolUseID, ".json")
   394→	return toolUseID, true
   395→}
