   397→// DetectChangedFiles detects files that have been modified, added, or deleted
   398→// since the last commit (or compared to the index for incremental checkpoints).
   399→// Returns three slices: modified files, new (untracked) files, and deleted files.
   400→// Excludes .entire/ directory from all results.
   401→func DetectChangedFiles() (modified, newFiles, deleted []string, err error) {
   402→	repo, err := openRepository()
   403→	if err != nil {
   404→		return nil, nil, nil, fmt.Errorf("failed to open repository: %w", err)
   405→	}
   406→
   407→	worktree, err := repo.Worktree()
   408→	if err != nil {
   409→		return nil, nil, nil, fmt.Errorf("failed to get worktree: %w", err)
   410→	}
   411→
   412→	status, err := worktree.Status()
   413→	if err != nil {
   414→		return nil, nil, nil, fmt.Errorf("failed to get status: %w", err)
   415→	}
   416→
   417→	for file, st := range status {
   418→		// Skip .entire directory
   419→		if paths.IsInfrastructurePath(file) {
   420→			continue
   421→		}
   422→
   423→		// Handle different status codes
   424→		// Worktree status indicates changes not yet staged
   425→		// Staging status indicates changes staged for commit
   426→		switch {
   427→		case st.Worktree == git.Untracked:
   428→			// New untracked file
   429→			newFiles = append(newFiles, file)
   430→		case st.Worktree == git.Deleted || st.Staging == git.Deleted:
   431→			// Deleted file
   432→			deleted = append(deleted, file)
   433→		case st.Worktree == git.Modified || st.Staging == git.Modified ||
   434→			st.Worktree == git.Added || st.Staging == git.Added:
   435→			// Modified or staged file
   436→			modified = append(modified, file)
   437→		}
   438→	}
   439→
   440→	return modified, newFiles, deleted, nil
   441→}
