   443→// GetNextCheckpointSequence returns the next sequence number for incremental checkpoints.
   444→// It counts existing checkpoint files in the task metadata checkpoints directory.
   445→// Returns 1 if no checkpoints exist yet.
   446→func GetNextCheckpointSequence(sessionID, taskToolUseID string) int {
   447→	// ctx.SessionID is already an Entire session ID (date-prefixed), so use SessionMetadataDirFromEntireID
   448→	sessionMetadataDir := paths.SessionMetadataDirFromEntireID(sessionID)
   449→	taskMetadataDir := strategy.TaskMetadataDir(sessionMetadataDir, taskToolUseID)
   450→	checkpointsDir := filepath.Join(taskMetadataDir, "checkpoints")
   451→
   452→	entries, err := os.ReadDir(checkpointsDir)
   453→	if err != nil {
   454→		// Directory doesn't exist or can't be read - start at 1
   455→		return 1
   456→	}
   457→
   458→	// Count JSON files (checkpoints)
   459→	count := 0
   460→	for _, entry := range entries {
   461→		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
   462→			count++
   463→		}
   464→	}
   465→
   466→	return count + 1
   467→}
