    24→// WriteCommitted writes a committed checkpoint to the entire/sessions branch.
    25→// Checkpoints are stored at sharded paths: <id[:2]>/<id[2:]>/
    26→//
    27→// For task checkpoints (IsTask=true), additional files are written under tasks/<tool-use-id>/:
    28→//   - For incremental checkpoints: checkpoints/NNN-<tool-use-id>.json
    29→//   - For final checkpoints: checkpoint.json and agent-<agent-id>.jsonl
    30→func (s *GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
    31→	_ = ctx // Reserved for future use
    32→
    33→	// Validate identifiers to prevent path traversal and malformed data
    34→	if err := paths.ValidateCheckpointID(opts.CheckpointID); err != nil {
    35→		return fmt.Errorf("invalid checkpoint options: %w", err)
    36→	}
    37→	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
    38→		return fmt.Errorf("invalid checkpoint options: %w", err)
    39→	}
    40→	if err := paths.ValidateToolUseID(opts.ToolUseID); err != nil {
    41→		return fmt.Errorf("invalid checkpoint options: %w", err)
    42→	}
    43→	if err := paths.ValidateAgentID(opts.AgentID); err != nil {
    44→		return fmt.Errorf("invalid checkpoint options: %w", err)
    45→	}
    46→
    47→	// Ensure sessions branch exists
    48→	if err := s.ensureSessionsBranch(); err != nil {
    49→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
    50→	}
    51→
    52→	// Get current branch tip and flatten tree
    53→	ref, entries, err := s.getSessionsBranchEntries()
    54→	if err != nil {
    55→		return err
    56→	}
    57→
    58→	// Use sharded path: <id[:2]>/<id[2:]>/
    59→	basePath := paths.CheckpointPath(opts.CheckpointID) + "/"
    60→
    61→	// Track task metadata path for commit trailer
    62→	var taskMetadataPath string
    63→
    64→	// Handle task checkpoints
    65→	if opts.IsTask && opts.ToolUseID != "" {
    66→		taskMetadataPath, err = s.writeTaskCheckpointEntries(opts, basePath, entries)
    67→		if err != nil {
    68→			return err
    69→		}
    70→	}
    71→
    72→	// Write standard checkpoint entries (transcript, prompts, context, metadata)
    73→	if err := s.writeStandardCheckpointEntries(opts, basePath, entries); err != nil {
    74→		return err
    75→	}
    76→
    77→	// Build and commit
    78→	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
    79→	if err != nil {
    80→		return err
    81→	}
    82→
    83→	commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
    84→	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, opts.AuthorName, opts.AuthorEmail)
    85→	if err != nil {
    86→		return err
    87→	}
    88→
    89→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
    90→	newRef := plumbing.NewHashReference(refName, newCommitHash)
    91→	if err := s.repo.Storer.SetReference(newRef); err != nil {
    92→		return fmt.Errorf("failed to set branch reference: %w", err)
    93→	}
    94→
    95→	return nil
    96→}
