    98→// getSessionsBranchEntries returns the sessions branch reference and flattened tree entries.
    99→func (s *GitStore) getSessionsBranchEntries() (*plumbing.Reference, map[string]object.TreeEntry, error) {
   100→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   101→	ref, err := s.repo.Reference(refName, true)
   102→	if err != nil {
   103→		return nil, nil, fmt.Errorf("failed to get sessions branch reference: %w", err)
   104→	}
   105→
   106→	parentCommit, err := s.repo.CommitObject(ref.Hash())
   107→	if err != nil {
   108→		return nil, nil, fmt.Errorf("failed to get commit object: %w", err)
   109→	}
   110→
   111→	baseTree, err := parentCommit.Tree()
   112→	if err != nil {
   113→		return nil, nil, fmt.Errorf("failed to get commit tree: %w", err)
   114→	}
   115→
   116→	entries := make(map[string]object.TreeEntry)
   117→	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
   118→		return nil, nil, err
   119→	}
   120→
   121→	return ref, entries, nil
   122→}
