   124→// writeTaskCheckpointEntries writes task-specific checkpoint entries and returns the task metadata path.
   125→func (s *GitStore) writeTaskCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (string, error) {
   126→	taskPath := basePath + "tasks/" + opts.ToolUseID + "/"
   127→
   128→	if opts.IsIncremental {
   129→		return s.writeIncrementalTaskCheckpoint(opts, taskPath, entries)
   130→	}
   131→	return s.writeFinalTaskCheckpoint(opts, taskPath, entries)
   132→}
