   134→// writeIncrementalTaskCheckpoint writes an incremental checkpoint file during task execution.
   135→func (s *GitStore) writeIncrementalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
   136→	checkpoint := incrementalCheckpointData{
   137→		Type:      opts.IncrementalType,
   138→		ToolUseID: opts.ToolUseID,
   139→		Timestamp: time.Now().UTC(),
   140→		Data:      opts.IncrementalData,
   141→	}
   142→	cpData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
   143→	if err != nil {
   144→		return "", fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
   145→	}
   146→	cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
   147→	if err != nil {
   148→		return "", fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
   149→	}
   150→
   151→	cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
   152→	cpPath := taskPath + "checkpoints/" + cpFilename
   153→	entries[cpPath] = object.TreeEntry{
   154→		Name: cpPath,
   155→		Mode: filemode.Regular,
   156→		Hash: cpBlobHash,
   157→	}
   158→	return cpPath, nil
   159→}
