   161→// writeFinalTaskCheckpoint writes the final checkpoint.json and subagent transcript.
   162→func (s *GitStore) writeFinalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
   163→	checkpoint := taskCheckpointData{
   164→		SessionID:      opts.SessionID,
   165→		ToolUseID:      opts.ToolUseID,
   166→		CheckpointUUID: opts.CheckpointUUID,
   167→		AgentID:        opts.AgentID,
   168→	}
   169→	checkpointData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
   170→	if err != nil {
   171→		return "", fmt.Errorf("failed to marshal task checkpoint: %w", err)
   172→	}
   173→	blobHash, err := CreateBlobFromContent(s.repo, checkpointData)
   174→	if err != nil {
   175→		return "", fmt.Errorf("failed to create task checkpoint blob: %w", err)
   176→	}
   177→
   178→	checkpointFile := taskPath + "checkpoint.json"
   179→	entries[checkpointFile] = object.TreeEntry{
   180→		Name: checkpointFile,
   181→		Mode: filemode.Regular,
   182→		Hash: blobHash,
   183→	}
   184→
   185→	// Write subagent transcript if available
   186→	if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
   187→		agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath)
   188→		if readErr == nil {
   189→			agentBlobHash, agentBlobErr := CreateBlobFromContent(s.repo, agentContent)
   190→			if agentBlobErr == nil {
   191→				agentPath := taskPath + "agent-" + opts.AgentID + ".jsonl"
   192→				entries[agentPath] = object.TreeEntry{
   193→					Name: agentPath,
   194→					Mode: filemode.Regular,
   195→					Hash: agentBlobHash,
   196→				}
   197→			}
   198→		}
   199→	}
   200→
   201→	// Return task path without trailing slash
   202→	return taskPath[:len(taskPath)-1], nil
   203→}
