   205→// writeStandardCheckpointEntries writes transcript, prompts, context, metadata.json and any additional files.
   206→// If the checkpoint already exists (from a previous session), archives the existing files to a numbered subfolder.
   207→func (s *GitStore) writeStandardCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   208→	// Check if checkpoint already exists (multi-session support)
   209→	var existingMetadata *CommittedMetadata
   210→	metadataPath := basePath + paths.MetadataFileName
   211→	if entry, exists := entries[metadataPath]; exists {
   212→		// Read existing metadata to get session count
   213→		existing, err := s.readMetadataFromBlob(entry.Hash)
   214→		if err == nil {
   215→			existingMetadata = existing
   216→			// Archive existing session files to numbered subfolder
   217→			s.archiveExistingSession(basePath, existingMetadata, entries)
   218→		}
   219→	}
   220→
   221→	// Write transcript (from in-memory content or file path)
   222→	if err := s.writeTranscript(opts, basePath, entries); err != nil {
   223→		return err
   224→	}
   225→
   226→	// Write prompts
   227→	if len(opts.Prompts) > 0 {
   228→		promptContent := strings.Join(opts.Prompts, "\n\n---\n\n")
   229→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
   230→		if err != nil {
   231→			return err
   232→		}
   233→		entries[basePath+paths.PromptFileName] = object.TreeEntry{
   234→			Name: basePath + paths.PromptFileName,
   235→			Mode: filemode.Regular,
   236→			Hash: blobHash,
   237→		}
   238→	}
   239→
   240→	// Write context
   241→	if len(opts.Context) > 0 {
   242→		blobHash, err := CreateBlobFromContent(s.repo, opts.Context)
   243→		if err != nil {
   244→			return err
   245→		}
   246→		entries[basePath+paths.ContextFileName] = object.TreeEntry{
   247→			Name: basePath + paths.ContextFileName,
   248→			Mode: filemode.Regular,
   249→			Hash: blobHash,
   250→		}
   251→	}
   252→
   253→	// Copy additional metadata files from directory if specified
   254→	if opts.MetadataDir != "" {
   255→		if err := s.copyMetadataDir(opts.MetadataDir, basePath, entries); err != nil {
   256→			return fmt.Errorf("failed to copy metadata directory: %w", err)
   257→		}
   258→	}
   259→
   260→	// Write metadata.json (with merged info if existing metadata present)
   261→	return s.writeMetadataJSON(opts, basePath, entries, existingMetadata)
   262→}
