   264→// writeTranscript writes the transcript file from in-memory content or file path.
   265→func (s *GitStore) writeTranscript(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   266→	transcript := opts.Transcript
   267→	if len(transcript) == 0 && opts.TranscriptPath != "" {
   268→		var readErr error
   269→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
   270→		if readErr != nil {
   271→			// Non-fatal: transcript may not exist yet
   272→			transcript = nil
   273→		}
   274→	}
   275→	if len(transcript) == 0 {
   276→		return nil
   277→	}
   278→
   279→	blobHash, err := CreateBlobFromContent(s.repo, transcript)
   280→	if err != nil {
   281→		return err
   282→	}
   283→	entries[basePath+paths.TranscriptFileName] = object.TreeEntry{
   284→		Name: basePath + paths.TranscriptFileName,
   285→		Mode: filemode.Regular,
   286→		Hash: blobHash,
   287→	}
   288→
   289→	// Content hash for deduplication
   290→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
   291→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
   292→	if err != nil {
   293→		return err
   294→	}
   295→	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
   296→		Name: basePath + paths.ContentHashFileName,
   297→		Mode: filemode.Regular,
   298→		Hash: hashBlob,
   299→	}
   300→	return nil
   301→}
