   303→// writeMetadataJSON writes the metadata.json file for the checkpoint.
   304→// If existingMetadata is provided, merges session info from the previous session(s).
   305→func (s *GitStore) writeMetadataJSON(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, existingMetadata *CommittedMetadata) error {
   306→	metadata := CommittedMetadata{
   307→		CheckpointID:           opts.CheckpointID,
   308→		SessionID:              opts.SessionID,
   309→		Strategy:               opts.Strategy,
   310→		CreatedAt:              time.Now(),
   311→		Branch:                 opts.Branch,
   312→		CheckpointsCount:       opts.CheckpointsCount,
   313→		FilesTouched:           opts.FilesTouched,
   314→		Agent:                  opts.Agent,
   315→		IsTask:                 opts.IsTask,
   316→		ToolUseID:              opts.ToolUseID,
   317→		SessionCount:           1,
   318→		SessionIDs:             []string{opts.SessionID},
   319→		TranscriptUUIDAtStart:  opts.TranscriptUUIDAtStart,
   320→		TranscriptLinesAtStart: opts.TranscriptLinesAtStart,
   321→		TokenUsage:             opts.TokenUsage,
   322→	}
   323→
   324→	// Merge with existing metadata if present (multi-session checkpoint)
   325→	if existingMetadata != nil {
   326→		// Get existing session count (default to 1 for backwards compat)
   327→		existingCount := existingMetadata.SessionCount
   328→		if existingCount == 0 {
   329→			existingCount = 1
   330→		}
   331→		metadata.SessionCount = existingCount + 1
   332→
   333→		// Merge session IDs
   334→		existingIDs := existingMetadata.SessionIDs
   335→		if len(existingIDs) == 0 {
   336→			// Backwards compat: old metadata only had SessionID
   337→			existingIDs = []string{existingMetadata.SessionID}
   338→		}
   339→		metadata.SessionIDs = append(metadata.SessionIDs[:0], existingIDs...)
   340→		metadata.SessionIDs = append(metadata.SessionIDs, opts.SessionID)
   341→
   342→		// Merge files touched (deduplicated)
   343→		metadata.FilesTouched = mergeFilesTouched(existingMetadata.FilesTouched, opts.FilesTouched)
   344→
   345→		// Sum checkpoint counts
   346→		metadata.CheckpointsCount = existingMetadata.CheckpointsCount + opts.CheckpointsCount
   347→	}
   348→
   349→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(metadata, "", "  ")
   350→	if err != nil {
   351→		return fmt.Errorf("failed to marshal metadata: %w", err)
   352→	}
   353→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   354→	if err != nil {
   355→		return err
   356→	}
   357→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
   358→		Name: basePath + paths.MetadataFileName,
   359→		Mode: filemode.Regular,
   360→		Hash: metadataHash,
   361→	}
   362→	return nil
   363→}
   364→
   365→// mergeFilesTouched combines two file lists, removing duplicates.
   366→func mergeFilesTouched(existing, additional []string) []string {
   367→	seen := make(map[string]bool)
   368→	var result []string
   369→
   370→	for _, f := range existing {
   371→		if !seen[f] {
   372→			seen[f] = true
   373→			result = append(result, f)
   374→		}
   375→	}
   376→	for _, f := range additional {
   377→		if !seen[f] {
   378→			seen[f] = true
   379→			result = append(result, f)
   380→		}
   381→	}
   382→
   383→	sort.Strings(result)
   384→	return result
   385→}
