   387→// readMetadataFromBlob reads CommittedMetadata from a blob hash.
   388→func (s *GitStore) readMetadataFromBlob(hash plumbing.Hash) (*CommittedMetadata, error) {
   389→	blob, err := s.repo.BlobObject(hash)
   390→	if err != nil {
   391→		return nil, fmt.Errorf("failed to get blob: %w", err)
   392→	}
   393→
   394→	reader, err := blob.Reader()
   395→	if err != nil {
   396→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
   397→	}
   398→	defer reader.Close()
   399→
   400→	var metadata CommittedMetadata
   401→	if err := json.NewDecoder(reader).Decode(&metadata); err != nil {
   402→		return nil, fmt.Errorf("failed to decode metadata: %w", err)
   403→	}
   404→
   405→	return &metadata, nil
   406→}
