   408→// archiveExistingSession moves existing session files to a numbered subfolder.
   409→// The subfolder number is based on the current session count (so first archived session goes to "1/").
   410→func (s *GitStore) archiveExistingSession(basePath string, existingMetadata *CommittedMetadata, entries map[string]object.TreeEntry) {
   411→	// Determine archive folder number
   412→	sessionCount := existingMetadata.SessionCount
   413→	if sessionCount == 0 {
   414→		sessionCount = 1 // backwards compat
   415→	}
   416→	archivePath := fmt.Sprintf("%s%d/", basePath, sessionCount)
   417→
   418→	// Files to archive (standard checkpoint files at basePath, excluding tasks/ subfolder)
   419→	filesToArchive := []string{
   420→		paths.MetadataFileName,
   421→		paths.TranscriptFileName,
   422→		paths.PromptFileName,
   423→		paths.ContextFileName,
   424→		paths.ContentHashFileName,
   425→	}
   426→
   427→	// Move each file to archive folder
   428→	for _, filename := range filesToArchive {
   429→		srcPath := basePath + filename
   430→		if entry, exists := entries[srcPath]; exists {
   431→			// Add to archive location
   432→			dstPath := archivePath + filename
   433→			entries[dstPath] = object.TreeEntry{
   434→				Name: dstPath,
   435→				Mode: entry.Mode,
   436→				Hash: entry.Hash,
   437→			}
