   444→// readArchivedSessions reads transcript data from archived session subfolders (1/, 2/, etc.).
   445→// Returns sessions ordered by folder index (oldest first).
   446→func (s *GitStore) readArchivedSessions(checkpointTree *object.Tree, sessionCount int) []ArchivedSession {
   447→	var archived []ArchivedSession
   448→
   449→	// Archived sessions are in numbered folders: 1/, 2/, etc.
   450→	// The most recent session is at the root level (not archived).
   451→	// Session count N means there are N-1 archived sessions.
   452→	for i := 1; i < sessionCount; i++ {
   453→		folderName := strconv.Itoa(i)
   454→
   455→		// Try to get the archived session subtree
   456→		subTree, err := checkpointTree.Tree(folderName)
   457→		if err != nil {
   458→			continue // Folder doesn't exist, skip
   459→		}
   460→
   461→		session := ArchivedSession{
   462→			FolderIndex: i,
   463→		}
   464→
   465→		// Read metadata to get session ID
   466→		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
   467→			if content, contentErr := metadataFile.Contents(); contentErr == nil {
   468→				var metadata CommittedMetadata
   469→				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
   470→					session.SessionID = metadata.SessionID
   471→				}
   472→			}
   473→		}
   474→
   475→		// Read transcript (try current format first, then legacy)
   476→		if file, fileErr := subTree.File(paths.TranscriptFileName); fileErr == nil {
   477→			if content, contentErr := file.Contents(); contentErr == nil {
   478→				session.Transcript = []byte(content)
   479→			}
   480→		} else if file, fileErr := subTree.File(paths.TranscriptFileNameLegacy); fileErr == nil {
   481→			if content, contentErr := file.Contents(); contentErr == nil {
   482→				session.Transcript = []byte(content)
   483→			}
   484→		}
   485→
   486→		// Read prompts
   487→		if file, fileErr := subTree.File(paths.PromptFileName); fileErr == nil {
   488→			if content, contentErr := file.Contents(); contentErr == nil {
   489→				session.Prompts = content
   490→			}
   491→		}
   492→
   493→		// Only add if we got a transcript
   494→		if len(session.Transcript) > 0 {
   495→			archived = append(archived, session)
   496→		}
   497→	}
   498→
   499→	return archived
   500→}
