   502→// buildCommitMessage constructs the commit message with proper trailers.
   503→// The commit subject is always "Checkpoint: <id>" for consistency.
   504→// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
   505→func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
   506→	var commitMsg strings.Builder
   507→
   508→	// Subject line is always the checkpoint ID for consistent formatting
   509→	commitMsg.WriteString(fmt.Sprintf("Checkpoint: %s\n\n", opts.CheckpointID))
   510→
   511→	// Include custom description in body if provided (e.g., task checkpoint details)
   512→	if opts.CommitSubject != "" {
   513→		commitMsg.WriteString(opts.CommitSubject + "\n\n")
   514→	}
   515→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", paths.SessionTrailerKey, opts.SessionID))
   516→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", paths.StrategyTrailerKey, opts.Strategy))
   517→	if opts.Agent != "" {
   518→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", paths.AgentTrailerKey, opts.Agent))
   519→	}
   520→	if opts.EphemeralBranch != "" {
   521→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", paths.EphemeralBranchTrailerKey, opts.EphemeralBranch))
   522→	}
   523→	if taskMetadataPath != "" {
   524→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", paths.MetadataTaskTrailerKey, taskMetadataPath))
   525→	}
   526→
   527→	return commitMsg.String()
   528→}
