   610→// ListCommitted lists all committed checkpoints from the entire/sessions branch.
   611→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
   612→//
   613→
   614→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
   615→	_ = ctx // Reserved for future use
   616→
   617→	tree, err := s.getSessionsBranchTree()
   618→	if err != nil {
   619→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
   620→	}
   621→
   622→	var checkpoints []CommittedInfo
   623→
   624→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
   625→	for _, bucketEntry := range tree.Entries {
   626→		if bucketEntry.Mode != filemode.Dir {
   627→			continue
   628→		}
   629→		// Bucket should be 2 hex chars
   630→		if len(bucketEntry.Name) != 2 {
   631→			continue
   632→		}
   633→
   634→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
   635→		if treeErr != nil {
   636→			continue
   637→		}
   638→
   639→		// Each entry in the bucket is the remaining part of the checkpoint ID
   640→		for _, checkpointEntry := range bucketTree.Entries {
   641→			if checkpointEntry.Mode != filemode.Dir {
   642→				continue
   643→			}
   644→
   645→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
   646→			if cpTreeErr != nil {
   647→				continue
   648→			}
   649→
   650→			// Reconstruct checkpoint ID: <bucket><remaining>
   651→			checkpointID := bucketEntry.Name + checkpointEntry.Name
   652→
   653→			info := CommittedInfo{
   654→				CheckpointID: checkpointID,
   655→			}
   656→
   657→			// Get details from metadata file
   658→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   659→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   660→					var metadata CommittedMetadata
   661→					if err := json.Unmarshal([]byte(content), &metadata); err == nil {
   662→						info.SessionID = metadata.SessionID
   663→						info.CreatedAt = metadata.CreatedAt
   664→						info.CheckpointsCount = metadata.CheckpointsCount
   665→						info.FilesTouched = metadata.FilesTouched
   666→						info.Agent = metadata.Agent
   667→						info.IsTask = metadata.IsTask
   668→						info.ToolUseID = metadata.ToolUseID
   669→						info.SessionCount = metadata.SessionCount
   670→						info.SessionIDs = metadata.SessionIDs
   671→					}
   672→				}
   673→			}
   674→
   675→			checkpoints = append(checkpoints, info)
   676→		}
   677→	}
   678→
   679→	// Sort by time (most recent first)
   680→	sort.Slice(checkpoints, func(i, j int) bool {
   681→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   682→	})
   683→
   684→	return checkpoints, nil
   685→}
