   750→// CreateBlobFromContent creates a blob object from in-memory content.
   751→// Exported for use by strategy package (session_test.go)
   752→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
   753→	obj := repo.Storer.NewEncodedObject()
   754→	obj.SetType(plumbing.BlobObject)
   755→	obj.SetSize(int64(len(content)))
   756→
   757→	writer, err := obj.Writer()
   758→	if err != nil {
   759→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
   760→	}
   761→
   762→	_, err = writer.Write(content)
   763→	if err != nil {
   764→		_ = writer.Close()
   765→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
   766→	}
   767→	if err := writer.Close(); err != nil {
   768→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
   769→	}
   770→
   771→	hash, err := repo.Storer.SetEncodedObject(obj)
   772→	if err != nil {
   773→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
   774→	}
   775→	return hash, nil
   776→}
