   778→// copyMetadataDir copies all files from a directory to the checkpoint path.
   779→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
   780→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
   781→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
   782→		if err != nil {
   783→			return err
   784→		}
   785→		if info.IsDir() {
   786→			return nil
   787→		}
   788→
   789→		// Skip symlinks to prevent reading files outside the metadata directory.
   790→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
   791→		// then be captured in the checkpoint and stored in git history.
   792→		if info.Mode()&os.ModeSymlink != 0 {
   793→			return nil
   794→		}
   795→
   796→		// Get relative path within metadata dir
   797→		relPath, err := filepath.Rel(metadataDir, path)
   798→		if err != nil {
   799→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
   800→		}
   801→
   802→		// Prevent path traversal via symlinks pointing outside the metadata dir
   803→		if strings.HasPrefix(relPath, "..") {
   804→			return fmt.Errorf("path traversal detected: %s", relPath)
   805→		}
   806→
   807→		// Create blob from file
   808→		blobHash, mode, err := createBlobFromFile(s.repo, path)
   809→		if err != nil {
   810→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
   811→		}
   812→
   813→		// Store at checkpoint path
   814→		fullPath := basePath + relPath
   815→		entries[fullPath] = object.TreeEntry{
   816→			Name: fullPath,
   817→			Mode: mode,
   818→			Hash: blobHash,
   819→		}
   820→
   821→		return nil
   822→	})
   823→	if err != nil {
   824→		return fmt.Errorf("failed to walk metadata directory: %w", err)
   825→	}
   826→	return nil
   827→}
