    59→// StateStore provides low-level operations for managing session state files.
    60→//
    61→// StateStore is a primitive for session state persistence. It is NOT the same as
    62→// the Sessions interface - it only handles state files in .git/entire-sessions/,
    63→// not the full session data which includes checkpoint content.
    64→//
    65→// Use StateStore directly in strategies for performance-critical state operations.
    66→// Use the Sessions interface (when implemented) for high-level session management.
    67→type StateStore struct {
    68→	// stateDir is the directory where session state files are stored
    69→	stateDir string
    70→}
