    76→	if err != nil {
    77→		return nil, fmt.Errorf("failed to get git common dir: %w", err)
    78→	}
    79→	return &StateStore{
    80→		stateDir: filepath.Join(commonDir, sessionStateDirName),
    81→	}, nil
    82→}
    83→
    84→// NewStateStoreWithDir creates a new state store with a custom directory.
    85→// This is useful for testing.
    86→func NewStateStoreWithDir(stateDir string) *StateStore {
    87→	return &StateStore{stateDir: stateDir}
