    90→// Load loads the session state for the given session ID.
    91→// Returns (nil, nil) when session file doesn't exist (not an error condition).
    92→func (s *StateStore) Load(ctx context.Context, sessionID string) (*State, error) {
    93→	_ = ctx // Reserved for future use
    94→
    95→	// Validate session ID to prevent path traversal
    96→	if err := paths.ValidateSessionID(sessionID); err != nil {
    97→		return nil, fmt.Errorf("invalid session ID: %w", err)
    98→	}
    99→
   100→	stateFile := s.stateFilePath(sessionID)
   101→
   102→	data, err := os.ReadFile(stateFile) //nolint:gosec // stateFile is derived from sessionID
   103→	if os.IsNotExist(err) {
   104→		return nil, nil //nolint:nilnil // nil,nil indicates session not found (expected case)
   105→	}
   106→	if err != nil {
   107→		return nil, fmt.Errorf("failed to read session state: %w", err)
   108→	}
   109→
   110→	var state State
   111→	if err := json.Unmarshal(data, &state); err != nil {
   112→		return nil, fmt.Errorf("failed to unmarshal session state: %w", err)
   113→	}
   114→	return &state, nil
   115→}
