   117→// Save saves the session state atomically.
   118→func (s *StateStore) Save(ctx context.Context, state *State) error {
   119→	_ = ctx // Reserved for future use
   120→
   121→	// Validate session ID to prevent path traversal
   122→	if err := paths.ValidateSessionID(state.SessionID); err != nil {
   123→		return fmt.Errorf("invalid session ID: %w", err)
   124→	}
   125→
   126→	if err := os.MkdirAll(s.stateDir, 0o750); err != nil {
   127→		return fmt.Errorf("failed to create session state directory: %w", err)
   128→	}
   129→
   130→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
   131→	if err != nil {
   132→		return fmt.Errorf("failed to marshal session state: %w", err)
   133→	}
   134→
   135→	stateFile := s.stateFilePath(state.SessionID)
   136→
   137→	// Atomic write: write to temp file, then rename
   138→	tmpFile := stateFile + ".tmp"
   139→	if err := os.WriteFile(tmpFile, data, 0o600); err != nil {
   140→		return fmt.Errorf("failed to write session state: %w", err)
   141→	}
   142→	if err := os.Rename(tmpFile, stateFile); err != nil {
   143→		return fmt.Errorf("failed to rename session state file: %w", err)
   144→	}
   145→	return nil
   146→}
