   148→// Clear removes the session state file for the given session ID.
   149→func (s *StateStore) Clear(ctx context.Context, sessionID string) error {
   150→	_ = ctx // Reserved for future use
   151→
   152→	// Validate session ID to prevent path traversal
   153→	if err := paths.ValidateSessionID(sessionID); err != nil {
   154→		return fmt.Errorf("invalid session ID: %w", err)
   155→	}
   156→
   157→	stateFile := s.stateFilePath(sessionID)
   158→
   159→	if err := os.Remove(stateFile); err != nil {
   160→		if os.IsNotExist(err) {
   161→			return nil // Already gone, not an error
   162→		}
   163→		return fmt.Errorf("failed to remove session state file: %w", err)
   164→	}
   165→	return nil
   166→}
