   168→// List returns all session states.
   169→func (s *StateStore) List(ctx context.Context) ([]*State, error) {
   170→	_ = ctx // Reserved for future use
   171→
   172→	entries, err := os.ReadDir(s.stateDir)
   173→	if os.IsNotExist(err) {
   174→		return nil, nil
   175→	}
   176→	if err != nil {
   177→		return nil, fmt.Errorf("failed to read session state directory: %w", err)
   178→	}
   179→
   180→	var states []*State
   181→	for _, entry := range entries {
   182→		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
   183→			continue
   184→		}
   185→		if strings.HasSuffix(entry.Name(), ".tmp") {
   186→			continue // Skip temp files
   187→		}
   188→
   189→		sessionID := strings.TrimSuffix(entry.Name(), ".json")
   190→		state, err := s.Load(ctx, sessionID)
   191→		if err != nil {
   192→			continue // Skip corrupted state files
   193→		}
   194→		if state == nil {
   195→			continue
   196→		}
   197→
   198→		states = append(states, state)
   199→	}
   200→	return states, nil
   201→}
