   203→// FindByBaseCommit finds all sessions based on the given commit hash.
   204→func (s *StateStore) FindByBaseCommit(ctx context.Context, baseCommit string) ([]*State, error) {
   205→	allStates, err := s.List(ctx)
   206→	if err != nil {
   207→		return nil, err
   208→	}
   209→
   210→	var matching []*State
   211→	for _, state := range allStates {
   212→		if state.BaseCommit == baseCommit {
   213→			matching = append(matching, state)
   214→		}
   215→	}
   216→	return matching, nil
   217→}
