   219→// FindByWorktree finds all sessions for the given worktree path.
   220→func (s *StateStore) FindByWorktree(ctx context.Context, worktreePath string) ([]*State, error) {
   221→	allStates, err := s.List(ctx)
   222→	if err != nil {
   223→		return nil, err
   224→	}
   225→
   226→	var matching []*State
