   240→// getGitCommonDir returns the path to the shared git directory.
   241→// In a regular checkout, this is .git/
   242→// In a worktree, this is the main repo's .git/ (not .git/worktrees/<name>/)
   243→func getGitCommonDir() (string, error) {
   244→	ctx := context.Background()
   245→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
   246→	cmd.Dir = "."
   247→	output, err := cmd.Output()
   248→	if err != nil {
   249→		return "", fmt.Errorf("failed to get git common dir: %w", err)
   250→	}
   251→
   252→	commonDir := strings.TrimSpace(string(output))
   253→
   254→	// git rev-parse --git-common-dir returns relative paths from the working directory,
   255→	// so we need to make it absolute if it isn't already
   256→	if !filepath.IsAbs(commonDir) {
   257→		commonDir = filepath.Join(".", commonDir)
   258→	}
   259→
   260→	return filepath.Clean(commonDir), nil
   261→}
   262→
   263→// GetWorktreePath returns the absolute path to the current worktree root.
   264→func GetWorktreePath() (string, error) {
   265→	ctx := context.Background()
   266→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--show-toplevel")
   267→	output, err := cmd.Output()
   268→	if err != nil {
   269→		return "", fmt.Errorf("failed to get worktree path: %w", err)
   270→	}
   271→	return strings.TrimSpace(string(output)), nil
   272→}
